class ConfidenceScaledCapTests(unittest.TestCase):
    """R407 (Session 95, Ben's decisions of 2026-09-23). Two caps scale with the
    input confidence the brief already reports.

    1905_10g built with no odds, no handedness, Savant data 23 days old and 12
    of 20 sides from a 48.9-day-old platoon file, and concentrated exactly as
    it would on a clean night. DEGRADED (one fact): player -0.05, cluster
    -0.10. SEVERE (two or more): -0.10 and -0.20.
    """

    CLEAN = {"f1_games_priced": 5, "f4_platoon_applied": 120, "hitters_in_pool": 160,
             "platoon_age_days": 2, "platoon_dependent_teams": ["NYY"],
             "savant_expected_stats": {
                 "expected_stats_batting.csv": {"age_days": 3.0, "stale": False},
                 "expected_stats_pitching.csv": {"age_days": 3.0, "stale": False}}}
    ONE_FACT = {
        "no_odds_priced": {"f1_games_priced": 0},
        "stale_platoon_reference": {"platoon_age_days": 48},
        "stale_savant_expected_stats": {"savant_expected_stats": {
            "expected_stats_batting.csv": {"age_days": 23.0, "stale": True},
            "expected_stats_pitching.csv": {"age_days": 3.0, "stale": False}}},
        "no_handedness": {"f4_platoon_applied": 0},
    }
    CONTROLS = {"max_player_exposure_pct": 0.40,
                "max_consensus_cluster_share_pct": 0.50,
                "max_team_exposure_pct": 0.70}

    def test_each_fact_alone_is_degraded(self):
        self.assertEqual(epi.resolve_input_confidence(self.CLEAN)["tier"], "clean")
        for name, change in self.ONE_FACT.items():
            with self.subTest(fact=name):
                conf = epi.resolve_input_confidence({**self.CLEAN, **change})
                self.assertEqual(conf["tier"], "degraded")
                self.assertEqual(conf["fired"], [name])

    def test_two_or_more_facts_are_severe_and_1905_10g_had_all_four(self):
        two = {**self.CLEAN, **self.ONE_FACT["no_odds_priced"],
               **self.ONE_FACT["no_handedness"]}
        self.assertEqual(epi.resolve_input_confidence(two)["tier"], "severe")
        all_four = dict(self.CLEAN)
        for change in self.ONE_FACT.values():
            all_four.update(change)
        conf = epi.resolve_input_confidence(all_four)
        self.assertEqual(conf["tier"], "severe")
        self.assertEqual(conf["fired"], list(epi.INPUT_CONFIDENCE_FACTS))

    def test_bens_schedule_moves_exactly_the_two_caps(self):
        for tier, player, cluster in (("degraded", 0.35, 0.40), ("severe", 0.30, 0.30)):
            with self.subTest(tier=tier):
                out, block = epi.apply_input_confidence(self.CONTROLS, {"tier": tier})
                self.assertEqual(out["max_player_exposure_pct"], player)
                self.assertEqual(out["max_consensus_cluster_share_pct"], cluster)
                self.assertEqual(out["max_team_exposure_pct"], 0.70, "no other cap moves")
                self.assertTrue(block["applied"])
                self.assertEqual(block["provenance"], "confidence_derived")
                self.assertEqual(
                    block["changes"]["max_player_exposure_pct"]["source"],
                    "confidence_derived")

    def test_a_clean_slate_and_an_unassessed_one_move_nothing(self):
        clean = epi.resolve_input_confidence(self.CLEAN)
        out, block = epi.apply_input_confidence(self.CONTROLS, clean)
        self.assertEqual(out, self.CONTROLS)
        self.assertFalse(block["applied"])
        unassessed = epi.resolve_input_confidence(None)
        self.assertEqual(unassessed["tier"], "not_assessed")
        out, block = epi.apply_input_confidence(self.CONTROLS, unassessed)
        self.assertEqual(out, self.CONTROLS)
        # An absent measurement is not a bad one.
        partial = epi.resolve_input_confidence({"f1_games_priced": None})
        self.assertEqual(partial["facts"]["no_odds_priced"]["state"], "unknown")
        self.assertEqual(partial["tier"], "clean")

    def test_the_feasibility_floor_wins(self):
        out, block = epi.apply_input_confidence(
            self.CONTROLS, {"tier": "severe"},
            floors={"max_player_exposure_pct": 0.38})
        self.assertEqual(out["max_player_exposure_pct"], 0.38)
        self.assertTrue(block["changes"]["max_player_exposure_pct"]["floor_won"])
        self.assertEqual(out["max_consensus_cluster_share_pct"], 0.30)

    def test_an_explicit_override_wins_and_an_off_cap_stays_off(self):
        out, block = epi.apply_input_confidence(
            {**self.CONTROLS, "max_consensus_cluster_share_pct": 1.0},
            {"tier": "severe"}, override_keys={"max_player_exposure_pct"})
        self.assertEqual(out["max_player_exposure_pct"], 0.40)
        self.assertEqual(block["changes"]["max_player_exposure_pct"]["source"],
                         "operator_override")
        self.assertEqual(out["max_consensus_cluster_share_pct"], 1.0)
        self.assertEqual(block["changes"]["max_consensus_cluster_share_pct"]["source"],
                         "off_stays_off")
        self.assertFalse(block["applied"])

    def test_the_deadline_relaxes_it_first_and_records_the_before_and_after(self):
        out, block = epi.apply_input_confidence(
            self.CONTROLS, {"tier": "severe"}, relax="deadline_t30")
        self.assertEqual(out, self.CONTROLS)
        change = block["changes"]["max_player_exposure_pct"]
        self.assertEqual((change["before"], change["after"], change["would_be"]),
                         (0.40, 0.40, 0.30))
        self.assertEqual(change["source"], "relaxed_deadline_t30")
        self.assertEqual(block["relaxed"], "deadline_t30")
        self.assertFalse(block["applied"])
        # build_slate: T-30 relaxes on the first solve, and a proven-infeasible
        # refusal with the tightening applied re-solves ONCE, relaxed, BEFORE the
        # deadline governor's loop is reached.
        src = (REPO / "skills" / "generate-lineups" / "scripts" / "build_slate.py"
               ).read_text(encoding="utf-8")
        run = src.split("def run_classic(", 1)[1]
        self.assertIn('"deadline_t30" if isinstance(_minutes, (int, float))', run)
        retry = run.index('confidence_relax = "proven_infeasible"')
        governor = run.index("governor = getattr(args, \"_governor\", None)")
        self.assertLess(retry, governor)

    def test_run_slate_applies_it_and_publishes_the_block(self):
        """On the vendored 2026-06-03 slate, whose tiny test fixtures cannot
        show a move (their feasibility floors lift both caps to 1.0)."""
        from tests import test_golden_replay as g
        salary, entries = g._find_archive_inputs(g.ARCHIVE_DIR)
        if salary is None or entries is None:
            self.skipTest("vendored data/archive/2026-06-03 inputs absent")
        rows = g._projection_rows_from_salary_csv(salary)
        severe_facts = {**self.CLEAN, "f1_games_priced": 0, "f4_platoon_applied": 0}
        with tempfile.TemporaryDirectory() as tmp:
            common = dict(salary_csv=salary, entries_csv=entries,
                          projection_mode="emergency_proxy",
                          contest_postures=g.PRODUCTION_POSTURES, approve=False)
            base = run_slate(runs_root=Path(tmp) / "a", projection_rows=[dict(r) for r in rows],
                             **common)
            severe = run_slate(runs_root=Path(tmp) / "b",
                               projection_rows=[dict(r) for r in rows],
                               input_confidence_facts=severe_facts, **common)
            relaxed = run_slate(runs_root=Path(tmp) / "c",
                                projection_rows=[dict(r) for r in rows],
                                input_confidence_facts=severe_facts,
                                input_confidence_relax="deadline_t30", **common)
        self.assertEqual(base["input_confidence"]["tier"], "not_assessed")
        self.assertEqual(base["merged_controls"]["max_player_exposure_pct"], 0.4)
        self.assertEqual(base["merged_controls"]["max_consensus_cluster_share_pct"], 0.5)
        block = severe["input_confidence"]
        self.assertEqual(block["tier"], "severe")
        self.assertEqual(severe["merged_controls"]["max_player_exposure_pct"], 0.3)
        self.assertEqual(severe["merged_controls"]["max_consensus_cluster_share_pct"], 0.3)
        self.assertEqual(block["changes"]["max_player_exposure_pct"]["before"], 0.4)
        self.assertEqual(severe["checkpoint_plan"]["feasibility"]["controls_feasibility"],
                         base["checkpoint_plan"]["feasibility"]["controls_feasibility"],
                         "the tightening is not a feasibility floor and is not reported as one")
        self.assertEqual(relaxed["merged_controls"]["max_player_exposure_pct"], 0.4)
        self.assertEqual(relaxed["input_confidence"]["relaxed"], "deadline_t30")

    def test_build_slate_reads_the_facts_off_the_briefs_own_blocks(self):
        bs = ConsensusClusterCapTests._build_slate()
        facts = bs.input_confidence_facts(
            {"counts": {"f1_games_priced": 0, "f4_platoon_applied": 0}},
            {"files": {"expected_stats_batting.csv": {"age_days": 23.0, "stale": True,
                                                       "exists": True},
                       "expected_stats_pitching.csv": {"age_days": None, "stale": False,
                                                        "exists": False},
                       "statsapi_season_pitching.csv": {"age_days": 1.0, "stale": False,
                                                         "exists": True}}},
            {"platoon_age_days": 48, "platoon_dependent_teams": ["CWS", "ATL"]},
            projection_frame(write_salary(Path(tempfile.mkdtemp()) / "s.csv")))
        self.assertEqual(facts["f1_games_priced"], 0)
        self.assertEqual(sorted(facts["savant_expected_stats"]), ["expected_stats_batting.csv"])
        self.assertGreater(facts["hitters_in_pool"], 0)
        conf = epi.resolve_input_confidence(facts)
        self.assertEqual(conf["tier"], "severe")
        self.assertEqual(len(conf["fired"]), 4)
        _, block = epi.apply_input_confidence(self.CONTROLS, conf)
        line = bs.format_input_confidence_line(block)
        self.assertIn("tier SEVERE", line)
        self.assertIn("max_player_exposure_pct 0.4 -> 0.3", line)
        self.assertIn("not a probability", line)
        self.assertTrue(bs.format_input_confidence_line(None).startswith("UNAVAILABLE"))


class ProjectionBackfillGradeTests(unittest.TestCase):
    """R408 (Session 96). `tools/replay_slate.py --grade-projection`: does the
    projection order players better than salary or APPG, on the archive?

    Observed outcomes only, one slate and one side at a time, never pooled. The
    premise was measured before building (dfs-premise): 9 gradeable Classic
    slates (7 in data/archive, 2 tracked fixtures), not the 5 the entry
    estimated, and contests map to a salary file through
    `field_miner.resolve_salary_file`, never by name overlap.
    """

    @staticmethod
    def _mod():
        import importlib
        if str(REPO / "tools") not in sys.path:
            sys.path.insert(0, str(REPO / "tools"))
        return importlib.import_module("replay_slate")

    def _grade_0603(self):
        mod = self._mod()
        if not (mod.ARCHIVE / "2026-06-03" / "DKSalaries_2026-06-03.csv").exists():
            self.skipTest("vendored data/archive/2026-06-03 absent")
        return mod.grade_projection(["2026-06-03"])

    def test_the_join_rate_is_reported_and_a_side_without_starters_says_why(self):
        result = self._grade_0603()
        self.assertEqual(result["slate_count"], 1)
        slate = result["slates"][0]
        self.assertEqual(slate["contests"], ["191020573", "191020574"])
        hitters = slate["sides"]["hitters"]
        self.assertEqual((hitters["pool"], hitters["n"], hitters["join_rate"]),
                         (36, 30, 0.8333))
        pitchers = slate["sides"]["pitchers"]
        self.assertFalse(pitchers["graded"])
        self.assertIn("no starting pitcher", pitchers["reason"])
        self.assertTrue(hitters["ceiling_rank_identical_to_engine_base"],
                        "without a live ceiling multiplier Ceiling is 1.42 x Base")

    def test_the_ranking_is_deterministic_and_the_spearman_is_tie_averaged(self):
        mod = self._mod()
        self.assertEqual(mod.spearman([1, 2, 3, 4], [10, 20, 30, 40]), 1.0)
        self.assertEqual(mod.spearman([1, 2, 3, 4], [40, 30, 20, 10]), -1.0)
        # Ranks [1.5, 1.5, 3, 4] against [4, 1, 2, 3]: cov 0.5, var 4.5 and 5.
        # Unaveraged ranks [1, 1, 3, 4] would give 0.0865 here.
        self.assertEqual(mod.spearman([1, 1, 2, 3], [4, 1, 2, 3]),
                         round(0.5 / math.sqrt(22.5), 4))
        self.assertIsNone(mod.spearman([1, 1, 1], [1, 2, 3]))
        first = json.dumps(self._grade_0603(), sort_keys=True, default=str)
        second = json.dumps(self._grade_0603(), sort_keys=True, default=str)
        self.assertEqual(first, second)

    def test_top_decile_and_tail_hits_on_a_hand_checked_toy(self):
        mod = self._mod()
        rows = []
        for i in range(20):
            rows.append({"player_id": f"p{i:02d}", "realized_cents": i * 100,
                         "engine_base": float(i), "ceiling": float(i),
                         "salary": float(19 - i),
                         "appg": float(19 if i == 0 else (18 if i == 19 else i - 1))})
        out = mod.grade_side(rows)
        # k = ceil(20 / 10) = 2; realized top two are p19, p18; p90 is the 18th
        # smallest value, 17.00.
        self.assertEqual(out["decile_size"], 2)
        self.assertEqual([mod.decile_size(n) for n in (1, 5, 10, 21)], [1, 1, 1, 3])
        self.assertEqual(out["realized_p90"], 17.0)
        p = out["predictors"]
        self.assertEqual((p["engine_base"]["top_decile_hits"], p["engine_base"]["tail_hits"]), (2, 2))
        self.assertEqual((p["salary"]["top_decile_hits"], p["salary"]["tail_hits"]), (0, 0))
        # appg's top two are p00 (19) and p19 (18): one hit, one tail hit.
        self.assertEqual((p["appg"]["top_decile_hits"], p["appg"]["tail_hits"]), (1, 1))
        self.assertEqual(out["leader"]["spearman"], "tie: ceiling, engine_base")
        self.assertEqual(p["salary"]["spearman"], -1.0)

    def test_nothing_is_pooled_across_slates_or_sides(self):
        result = self._grade_0603()
        self.assertFalse({"spearman", "pooled", "overall", "mean_spearman"}
                         & set(result), "a cross-slate statistic is a pooled number")
        count = result["observed_outcome_count"]
        self.assertIn("observed-outcome COUNT, not a pooled statistic", count["line"])
        self.assertEqual(set(count["by_side"]), {"hitters"})
        self.assertEqual(count["by_side"]["hitters"]["slate_sides"], 1)

    def test_no_post_dated_input_reaches_the_prior(self):
        """R251 has not landed and every stored enrichment input post-dates the
        archived slates, so the frame is rebuilt on date-independent factors,
        with the platoon reference WITHHELD. Left to its default, the intake
        loads today's platoon file into a June slate and F2 goes live."""
        mod = self._mod()
        result = self._grade_0603()
        live = result["slates"][0]["live_factors"]
        self.assertFalse(live["batting_order_F2"])
        self.assertEqual(live["platoon_source"], "withheld")
        for key in ("platoon_reference", "savant_xwoba_xiso", "fangraphs_k_rate",
                    "odds_F1", "matchup_F4", "weather_F5"):
            self.assertFalse(live[key], key)
        src = inspect.getsource(mod.slate_groups)
        self.assertIn("resolve_salary_file(", src, "contests map through the miner's resolver")

    def test_the_labels_are_present_and_the_table_carries_them(self):
        mod = self._mod()
        result = self._grade_0603()
        for phrase in ("observed outcomes", "never pooled", "never ROI", "probability"):
            self.assertIn(phrase, result["label"])
        table = mod.format_grade_table(result)
        self.assertTrue(table.startswith("# observed outcomes"))
        self.assertIn("not a probability", table)


class ClassicSleeveTests(unittest.TestCase):
    """R406 (Session 94, Ben's decisions of 2026-09-23). Classic scenario
    sleeves: the portfolio is built across worlds where the projection is wrong
    in named ways -- the projection itself, salary as the only prior,
    chalk-fails (at most one of R405's cluster), and the top environment games
    -- and each entry is confined to one sleeve through the allocator's own
    compatibility mask, so every cap still binds across the whole entered set.
    """

    @staticmethod
    def _cs():
        from mlb_engine.optimize import classic_sleeves
        return classic_sleeves

    def test_the_salary_only_transform_keeps_no_player_level_factor(self):
        cs = self._cs()
        frame = diverse_projection_frame()
        frame["Base"] = frame["Floor"] * 1.6
        # Two same-salary hitters the projection separates, one of them with an
        # extreme ceiling: in the salary world they must be the same player.
        frame.loc[frame["Player_ID"] == "21001", ["Base", "Ceiling"]] = [20.0, 60.0]
        before = frame.copy()
        out, report = cs.salary_only_frame(frame)
        self.assertTrue(frame.equals(before), "the transform is a copy, never an edit")
        hitters = out[out["Position"] != "P"]
        self.assertEqual(hitters[["Base", "Ceiling", "Floor"]].drop_duplicates().shape[0], 1,
                         "same salary must mean the same Base, Ceiling and Floor")
        self.assertEqual(set(out["Player_ID"]), set(frame["Player_ID"]), "no player dropped")
        self.assertEqual(sorted(report["groups"]), ["hitters", "pitchers"])

    def test_largest_remainder_apportionment_and_the_wta_tilt(self):
        cs = self._cs()
        self.assertEqual(cs.DEFAULT_WEIGHTS, {"projection": 0.40, "salary_only": 0.20,
                                              "chalk_fails": 0.20, "environment": 0.20})
        self.assertEqual(cs.WTA_WEIGHTS, {"projection": 0.30, "salary_only": 0.20,
                                          "chalk_fails": 0.30, "environment": 0.20})
        self.assertEqual(cs.largest_remainder(34, cs.DEFAULT_WEIGHTS),
                         {"projection": 13, "salary_only": 7, "chalk_fails": 7, "environment": 7})
        # 7 x (0.3, 0.2, 0.3, 0.2): floors 2/1/2/1, the one left goes to the
        # largest remainder, salary and environment tie at 0.4 and SLEEVES
        # order breaks it.
        self.assertEqual(cs.largest_remainder(7, cs.WTA_WEIGHTS),
                         {"projection": 2, "salary_only": 2, "chalk_fails": 2, "environment": 1})
        self.assertEqual(cs.weights_for_contest("wta_satellite", "large_field_gpp"), cs.WTA_WEIGHTS)
        self.assertEqual(cs.weights_for_contest("large_gpp", "large_wta"), cs.WTA_WEIGHTS)
        self.assertEqual(cs.weights_for_contest("large_gpp", "large_field_gpp"), cs.DEFAULT_WEIGHTS)

    def test_single_entry_and_cash_go_to_projection(self):
        cs = self._cs()
        self.assertEqual(cs.contest_sleeve_weights("single_entry", "single_entry_gpp"),
                         {"projection": 1.0})
        self.assertEqual(cs.contest_sleeve_weights("cash", "cash"), {"projection": 1.0})
        reqs = [{"entry_id": "a", "contest_id": "1"},
                {"entry_id": "b", "contest_id": "2"}, {"entry_id": "c", "contest_id": "2"}]
        plan = cs.apportion_entries(reqs, {"1": cs.DEFAULT_WEIGHTS,
                                           "2": {"projection": 1.0}})
        self.assertEqual(set(plan["sleeve_by_entry"].values()), {"projection"},
                         "one entry, or a projection-only contest, seats projection")

    def test_environment_game_ranking_and_its_tie_break(self):
        cs = self._cs()
        teams = {"A@B": ["A", "B"], "C@D": ["C", "D"], "E@F": ["E", "F"]}
        ranked = cs.rank_environment_games(
            teams, implied_total_by_team={"A": 4.0, "B": 4.0, "C": 5.0, "D": 4.5,
                                          "E": 4.0, "F": 4.0},
            teams_by_game=teams)
        self.assertEqual(ranked["basis"], "implied_total")
        self.assertEqual(ranked["games"], ["C@D", "A@B"], "9.5 first, then the 8.0 tie by id")
        parks = cs.rank_environment_games(teams, park_run_factor_by_game={
            "A@B": 1.0, "C@D": 1.2, "E@F": 1.2}, teams_by_game=teams)
        self.assertEqual((parks["basis"], parks["games"]), ("park_run_factor", ["C@D", "E@F"]))
        self.assertEqual(cs.static_park_run_factor_by_game(["BOS@NYY"]),
                         {"BOS@NYY": cs.static_park_run_factor_by_game(["X@NYY"])["X@NYY"]},
                         "the home venue's factor, from the reference tables F5 reads")
        # Two games on a two-game slate are the whole slate: the request drops
        # the sleeve rather than repeat the projection's job grid.
        frame = diverse_projection_frame()
        reqs = [{"entry_id": str(i), "contest_id": "9", "posture": "large_gpp",
                 "contest_shape": "large_field_gpp"} for i in range(10)]
        implied = {"T1": 4.0, "T2": 4.1, "T3": 5.0, "T4": 4.4}
        req = epi.resolve_sleeve_bank_request(reqs, {}, frame, implied_total_by_team=implied)
        self.assertNotIn("environment", req["sleeves"])
        self.assertIn("whole slate", req["dropped"]["environment"])
        self.assertEqual(req["expected_entries"], {"projection": 4, "salary_only": 2,
                                                   "chalk_fails": 2, "environment": 2})
        off = epi.resolve_sleeve_bank_request(reqs, {"classic_sleeves": False}, frame)
        self.assertFalse(off["active"])

    def test_chalk_fails_and_environment_jobs_carry_their_constraints(self):
        cs = self._cs()
        frame = diverse_projection_frame()
        with tempfile.TemporaryDirectory() as tmp:
            cache = bank_cache.BankCache(Path(tmp) / "b.json")
            salary = bank_cache.BankCache(Path(tmp) / "s.json")
            bank_cache.extend_bank(cache, frame, time_budget_s=60)
            n_ordinary = len(cache)
            members = ca.consensus_cluster_members(cache.as_candidates(None))["member_ids"]
            request = {"active": True, "environment": {"teams": ["T3", "T4"]},
                       "sleeves": {"chalk_fails": {"min_candidates": 4},
                                   "environment": {"min_candidates": 4},
                                   "salary_only": {"min_candidates": 4}}}
            jobs = epi.build_sleeve_jobs(cache, frame, request, consensus_members=members,
                                         time_budget_s=120, salary_cache=salary)
            self.assertTrue(jobs["sleeves"]["chalk_fails"]["attempted"], jobs)
            self.assertTrue(jobs["sleeves"]["salary_only"]["attempted"], jobs)
            # The exhausted ordinary bank already holds lineups stacking T3/T4,
            # so the restricted grid is skipped rather than re-solved to the
            # same lineups; a thin bank runs it for depth.
            env_job = jobs["sleeves"]["environment"]
            self.assertFalse(env_job["attempted"])
            self.assertGreaterEqual(env_job["already_held"], 4)
            thin = bank_cache.BankCache(Path(tmp) / "thin.json")
            bank_cache.extend_bank(thin, frame, time_budget_s=60, max_candidates=2)
            thin_jobs = epi.build_sleeve_jobs(
                thin, frame, {**request, "sleeves": {"environment": {"min_candidates": 4}}},
                consensus_members=members, time_budget_s=120)
            self.assertTrue(thin_jobs["sleeves"]["environment"]["attempted"], thin_jobs)
            self.assertGreater(thin_jobs["sleeves"]["environment"]["built"], 0)
            thin_env = [c for c in cs.tag_sleeves(thin.as_candidates(frame), ["T3", "T4"])
                        if c.get("bank_job_class") == "sleeve_environment"]
            self.assertTrue(thin_env and all(c["primary_stack"] in ("T3", "T4") for c in thin_env))
            tagged = cs.tag_sleeves(cache.as_candidates(frame), ["T3", "T4"])
            chalk = [c for c in tagged if c.get("bank_sleeve") == "chalk_fails"]
            env = [c for c in tagged if "environment" in c["bank_sleeves"]]
            self.assertTrue(all("projection" in c["bank_sleeves"] for c in env),
                            "an environment lineup is a projection-world lineup")
            self.assertFalse(any("environment" in c["bank_sleeves"] for c in chalk))
            self.assertTrue(chalk and env, (len(chalk), len(env)))
            for c in chalk:
                self.assertLessEqual(ca.consensus_member_count(c["player_ids"], members), 1)
            team_of = dict(zip(frame["Player_ID"].astype(str), frame["Team"].astype(str)))
            for c in env:
                self.assertIn(c["primary_stack"], {"T3", "T4"})
            # Fillers from the other game stay legal: no pool reduction.
            self.assertTrue(any(team_of[p] in ("T1", "T2") for c in env
                                for p in c["player_ids"][2:]),
                            "environment lineups may still roster any team's fillers")
            sal = epi.sleeve_candidates(cache, salary, frame, requested_n=4)
            self.assertTrue(sal and all(c["bank_sleeve"] == "salary_only" for c in sal))
            self.assertTrue(all(c["candidate_id"].startswith("sal") for c in sal),
                            "salary-only ids cannot collide with the ordinary bank's")
            self.assertGreater(len(cache), n_ordinary)

    @staticmethod
    def _bank():
        """Ten projection lineups (100-i) and three per sleeve (60-i), all distinct."""
        out = []
        for i in range(10):
            out.append({"candidate_id": f"P{i}",
                        "roster_slot_ids": [f"pa{i}", f"pb{i}"] + [f"ph{i}_{j}" for j in range(7)] + ["star"],
                        "sp_ids": [f"pa{i}", f"pb{i}"], "primary_stack": "", "objective": 100.0 - i})
        for sleeve in ("salary_only", "chalk_fails"):
            for i in range(3):
                out.append({"candidate_id": f"{sleeve}{i}",
                            "roster_slot_ids": [f"{sleeve}a{i}", f"{sleeve}b{i}"]
                            + [f"{sleeve}h{i}_{j}" for j in range(7)] + ["star"],
                            "sp_ids": [f"{sleeve}a{i}", f"{sleeve}b{i}"], "primary_stack": "",
                            "objective": 60.0 - i, "bank_sleeve": sleeve})
        return out

    @staticmethod
    def _entries(n=5, posture="large_gpp", shape="large_field_gpp"):
        return [{"entry_id": f"e{i}", "contest_id": "C1", "contest_name": "T",
                 "contest_shape": shape, "posture": posture} for i in range(n)]

    def test_the_mask_confines_each_entry_to_its_sleeve(self):
        out = ca.select_and_assign_entries(self._bank(), self._entries(),
                                           {"max_candidate_reuse": 5})
        self.assertTrue(out["passed"], out.get("errors"))
        block = out["classic_sleeves"]
        self.assertEqual(block["status"], "applied")
        # 5 x (0.4, 0.2, 0.2, 0.2) = 2/1/1/1; environment has no candidate here
        # and falls back to projection, counted.
        self.assertEqual(block["entries_by_sleeve"]["C1"],
                         {"projection": 3, "salary_only": 1, "chalk_fails": 1, "environment": 0})
        self.assertEqual(block["relaxations"], 1)
        by_id = {c["candidate_id"]: c for c in self._bank()}
        for a in out["assignments"]:
            want = block["sleeve_by_entry"][a["entry_id"]]
            self.assertEqual(by_id[a["candidate_id"]].get("bank_sleeve", "projection"), want)
        self.assertEqual(set(block["delivered"]), {"projection", "salary_only", "chalk_fails"})

    def test_environment_entries_seat_on_projection_lineups_stacking_the_chosen_games(self):
        """The environment sleeve is a MEMBERSHIP: a projection-world lineup
        whose primary stack is a chosen game's team may seat an environment
        entry (and a projection one); nothing else may."""
        cs = self._cs()
        bank = self._bank()
        for c in bank[:4]:
            c["primary_stack"] = "T3"
        tagged = cs.tag_sleeves(bank, ["T3", "T4"])
        out = ca.select_and_assign_entries(tagged, self._entries(), {"max_candidate_reuse": 5})
        self.assertTrue(out["passed"], out.get("errors"))
        block = out["classic_sleeves"]
        self.assertEqual(block["entries_by_sleeve"]["C1"]["environment"], 1)
        self.assertEqual(block["candidates_by_sleeve"]["environment"], 4)
        by_id = {c["candidate_id"]: c for c in tagged}
        for a in out["assignments"]:
            if block["sleeve_by_entry"][a["entry_id"]] == "environment":
                self.assertEqual(by_id[a["candidate_id"]]["primary_stack"], "T3")

    def test_caps_still_bind_across_sleeves(self):
        """`star` is in every candidate of every sleeve: a player cap of 0.4
        over 5 entries allows 2, so no assignment exists -- the cap is joint
        across sleeves, not per sleeve, and the refusal says so."""
        out = ca.select_and_assign_entries(
            self._bank(), self._entries(),
            {"max_candidate_reuse": 5, "max_player_exposure_pct": 0.4})
        self.assertFalse(out["passed"])
        self.assertEqual(out["classic_sleeves"]["status"], "applied")
        uncapped_star = ca.select_and_assign_entries(
            [dict(c, roster_slot_ids=c["roster_slot_ids"][:-1] + [f"x{k}"])
             for k, c in enumerate(self._bank())],
            self._entries(), {"max_candidate_reuse": 5, "max_player_exposure_pct": 0.4})
        self.assertTrue(uncapped_star["passed"], uncapped_star.get("errors"))

    def test_a_bank_without_sleeves_or_with_them_off_changes_nothing(self):
        plain = [c for c in self._bank() if not c.get("bank_sleeve")]
        base = ca.select_and_assign_entries(plain, self._entries(), {"max_candidate_reuse": 5})
        self.assertEqual(base["classic_sleeves"]["status"], "no_sleeve_bank")
        off = ca.select_and_assign_entries(self._bank(), self._entries(),
                                           {"max_candidate_reuse": 5, "classic_sleeves": False})
        self.assertEqual(off["classic_sleeves"]["status"], "off")
        self.assertTrue(all(a["candidate_id"].startswith("P") for a in off["assignments"]),
                        "off, the projection lineups win every seat on score")

    def test_a_sleeve_too_thin_for_its_entries_falls_back_and_is_counted(self):
        # WTA tilt over 10 entries: 3/2/3/2; chalk-fails holds 3 distinct
        # lineups for its 3 seats, salary-only 3 for 2, environment none.
        out = ca.select_and_assign_entries(
            self._bank(), self._entries(10, posture="wta_satellite", shape="large_wta"),
            {"max_candidate_reuse": 10})
        self.assertTrue(out["passed"], out.get("errors"))
        seats = out["classic_sleeves"]["entries_by_sleeve"]["C1"]
        self.assertEqual(seats, {"projection": 5, "salary_only": 2, "chalk_fails": 3,
                                 "environment": 0})
        thin = [b for b in self._bank() if b.get("bank_sleeve") != "chalk_fails"
                or b["candidate_id"] == "chalk_fails0"]
        out = ca.select_and_assign_entries(
            thin, self._entries(10, posture="wta_satellite", shape="large_wta"),
            {"max_candidate_reuse": 10})
        self.assertTrue(out["passed"], out.get("errors"))
        block = out["classic_sleeves"]
        self.assertEqual(block["entries_by_sleeve"]["C1"]["chalk_fails"], 1)
        self.assertTrue(any("distinct compatible lineup" in f["reason"] for f in block["fallbacks"]))
        self.assertEqual(block["relaxations"], 2 + 2)

    def test_every_door_builds_the_sleeves_through_one_helper(self):
        pipeline = (REPO / "mlb_engine" / "pipeline" / "execution_pipeline.py").read_text(
            encoding="utf-8")
        run = pipeline.split("def run_slate(", 1)[1]
        self.assertIn("candidates, sleeve_jobs = _direct_door_sleeves(", run)
        plan = pipeline.split("def _plan_joint_allocation(", 1)[1].split("\ndef ", 1)[0]
        self.assertIn("build_sleeve_jobs(", plan)
        slate = (REPO / "skills" / "generate-lineups" / "scripts" / "build_slate.py"
                 ).read_text(encoding="utf-8")
        self.assertIn("sleeve_jobs = build_sleeve_jobs(", slate)
        self.assertIn('BankCache(bank_path.with_name(bank_path.stem + "_salary_only.json"))', slate)

    def test_the_brief_line_names_the_sleeves_and_the_fallbacks(self):
        out = ca.select_and_assign_entries(self._bank(), self._entries(),
                                           {"max_candidate_reuse": 5})
        bs = ConsensusClusterCapTests._build_slate()
        line = bs.format_sleeves_line({**out["classic_sleeves"], "request": {
            "environment": {"games": ["C@D"], "basis": "implied_total"}}})
        self.assertIn("projection 3", line)
        self.assertIn("environment games C@D (by implied_total)", line)
        self.assertIn("1 entr(ies) fell back to projection", line)
        self.assertIn("not probabilities", line)
        self.assertTrue(bs.format_sleeves_line(None).startswith("not applied"))
